import 'package:dartz/dartz.dart';import 'package:dio/dio.dart';import 'package:zan/Features/client/App/Cart/data/entity/coupons_model.dart';import 'package:zan/Features/client/App/Cart/data/entity/removed_coupons.dart';import '../../../../../../Core/Models/cart_itemes.dart';import '../../../../../../Core/Storage/Remote/api_error_handler.dart';import '../../data/Sources/cart_sources.dart';import '../../data/repositories/cart_repo.dart';class CartRepoImpl extends CartRepo {  @override  Future<Either<Failure, CartItemsModel>> removeFromCart({required int id}) async{    try {      final response = await CartSources.removeFromCart(id: id,);      return right(response);    } on DioException catch (e) {      return Left(ServerFailure.fromDioError(e));    } catch (e) {      return Left(ServerFailure("Unknown error occurred"));    }  }  @override  Future<Either<Failure, CartItemsModel>> updateFromCart({required int id ,required int newQuantity}) async{    try {      final response = await CartSources.updateFromCart(id: id,newQuantity: newQuantity);      return right(response);    } on DioException catch (e) {      return Left(ServerFailure.fromDioError(e));    } catch (e) {      return Left(ServerFailure("Unknown error occurred"));    }  }  @override  Future<Either<Failure, CartItemsModel>> getCarts() async{    try {      final response = await CartSources.getCarts();      return right(response);    } on DioException catch (e) {      return Left(ServerFailure.fromDioError(e));    } catch (e) {      return Left(ServerFailure("Unknown error occurred"));    }  }  @override  Future<Either<Failure, CartItemsModel>> clearCart() async{    try {      final response = await CartSources.clearCart();      return right(response);    } on DioException catch (e) {      return Left(ServerFailure.fromDioError(e));    } catch (e) {      return Left(ServerFailure("Unknown error occurred"));    }  }  @override  Future<Either<Failure, CouponsModel>> applyCoupon({required String code}) async{    try {      final response = await CartSources.applyCoupon(code: code);      return right(response);    } on DioException catch (e) {      return Left(ServerFailure.fromDioError(e));    } catch (e) {      return Left(ServerFailure("Unknown error occurred"));    }  }  @override  Future<Either<Failure, RemovedCouponsModel>> removeCoupon({required String code}) async{    try {      final response = await CartSources.removeCoupon(code: code);      return right(response);    } on DioException catch (e) {      return Left(ServerFailure.fromDioError(e));    } catch (e) {      return Left(ServerFailure("Unknown error occurred"));    }  }}